<?php /** Template Name: Producer Portal */ if(!defined('ABSPATH'))exit;if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/producer-portal/')));exit;}if(!tuff_beatz_is_producer_user()){wp_safe_redirect(home_url('/client-portal/'));exit;}
$q=new WP_Query(array('post_type'=>'tb_request','post_status'=>'publish','posts_per_page'=>100,'orderby'=>'date','order'=>'DESC'));$projects=$q->posts;$counts=array('new'=>0,'reviewing'=>0,'approved'=>0,'in-progress'=>0,'revision'=>0,'mastering'=>0,'delivery'=>0,'completed'=>0);$attention_items=array();$deadlines=array();$activity_feed=array();$payment_due=0;$unread_messages=0;$now=current_time('timestamp');$producer_uid=get_current_user_id();
foreach($projects as $p){$id=$p->ID;$s=get_post_meta($id,'_tb_request_status',true)?:'new';if(isset($counts[$s]))$counts[$s]++;$artist=get_post_meta($id,'_tb_request_artist',true)?:'Client';$pay=get_post_meta($id,'_tb_request_payment_status',true);$msg_unread=function_exists('tuff_beatz_conversation_unread')?tuff_beatz_conversation_unread($id,$producer_uid):0;$unread_messages+=$msg_unread;if($msg_unread)$attention_items[]=array('kind'=>'MESSAGE','title'=>$p->post_title,'meta'=>$msg_unread.' unread message'.($msg_unread===1?'':'s'),'id'=>$id,'priority'=>5);if(in_array($pay,array('Deposit due','Balance due'),true)){$payment_due++;$attention_items[]=array('kind'=>'PAYMENT','title'=>$p->post_title,'meta'=>$pay,'id'=>$id,'priority'=>2);}if(in_array($s,array('new','revision'),true))$attention_items[]=array('kind'=>$s==='new'?'NEW INTAKE':'REVISION','title'=>$p->post_title,'meta'=>$artist,'id'=>$id,'priority'=>$s==='revision'?3:2);
 if(function_exists('tuff_beatz_project_milestones')){foreach(tuff_beatz_project_milestones($id) as $m){$due=$m['due_date']??'';$ms=$m['status']??'pending';if($due&&$ms!=='completed'){$ts=strtotime($due.' 23:59:59');$deadlines[]=array('title'=>$m['title']??'Milestone','project'=>$p->post_title,'due'=>$due,'ts'=>$ts,'id'=>$id,'over'=>$ts<$now);if($ts<$now)$attention_items[]=array('kind'=>'OVERDUE','title'=>$p->post_title,'meta'=>($m['title']??'Milestone').' overdue','id'=>$id,'priority'=>4);}}}
 if(function_exists('tuff_beatz_project_activity')){foreach(array_slice(array_reverse(tuff_beatz_project_activity($id)),0,5) as $a){$activity_feed[]=array('message'=>$a['message']??'Project update','time'=>$a['time']??$p->post_date,'project'=>$p->post_title,'id'=>$id,'type'=>$a['type']??'update');}}
}
usort($deadlines,function($a,$b){return $a['ts']<=>$b['ts'];});usort($activity_feed,function($a,$b){return strtotime($b['time'])<=>strtotime($a['time']);});usort($attention_items,function($a,$b){return $b['priority']<=>$a['priority'];});
$active=$counts['new']+$counts['reviewing']+$counts['approved']+$counts['in-progress']+$counts['revision']+$counts['mastering']+$counts['delivery'];$attention=count($attention_items);$latest=$projects?reset($projects):null;$stage=sanitize_key($_GET['stage']??'all');$search=sanitize_text_field(wp_unslash($_GET['tbq']??''));$filtered=array_values(array_filter($projects,function($p)use($stage,$search){$s=get_post_meta($p->ID,'_tb_request_status',true)?:'new';if($stage!=='all'&&$s!==$stage)return false;if($search){$hay=strtolower($p->post_title.' '.get_post_meta($p->ID,'_tb_request_artist',true).' '.get_post_meta($p->ID,'_tb_request_email',true));if(strpos($hay,strtolower($search))===false)return false;}return true;}));get_header();?>
<main class="tb-hub tb-producer-hub tb-command-v2">
<section class="tb-command-hero"><div class="container tb-command-hero-grid"><div class="tb-command-hero-copy"><p class="eyebrow">TUFF BEATZ • PRIVATE STUDIO OS</p><h1>Production<br>Command Center</h1><p>One executive workspace for clients, projects, files, reviews, contracts, payments and delivery.</p><div class="tb-hub-actions"><a class="btn btn-gold" href="<?php echo esc_url(home_url('/start-a-project/'));?>">+ New Intake</a><a class="btn btn-outline" href="<?php echo esc_url(home_url('/producer-crm/'));?>">Client CRM</a><a class="btn btn-outline" href="<?php echo esc_url(admin_url('edit.php?post_type=tb_request'));?>">Project Admin</a></div></div><aside class="tb-command-live"><div class="tb-command-live-top"><span><i></i> LIVE OPERATIONS</span><small><?php echo esc_html(wp_date('M j, Y'));?></small></div><strong><?php echo esc_html($active);?></strong><p>active production<?php echo $active===1?'':'s';?></p><div class="tb-command-live-grid"><div><small>Needs Attention</small><b><?php echo esc_html($attention);?></b></div><div><small>Unread Messages</small><b class="<?php echo $unread_messages?'has-unread':'';?>"><?php echo esc_html($unread_messages);?></b></div><div><small>Payment Due</small><b><?php echo esc_html($payment_due);?></b></div><div><small>Completed</small><b><?php echo esc_html($counts['completed']);?></b></div></div><?php if($latest):?><a class="tb-command-latest" href="<?php echo esc_url(tuff_beatz_project_dashboard_url($latest->ID));?>"><span>Latest Project</span><b><?php echo esc_html($latest->post_title);?></b><em>Open Workspace →</em></a><?php endif;?></aside></div></section>
<section class="section tb-command-overview"><div class="container"><div class="tb-command-section-head"><div><p class="tb-card-kicker">EXECUTIVE OVERVIEW</p><h2>Studio Pipeline</h2></div><span><?php echo esc_html($active);?> ACTIVE</span></div><div class="tb-command-bento"><a class="tb-command-feature" href="<?php echo esc_url(add_query_arg('stage','in-progress',home_url('/producer-portal/')));?>"><small>CURRENT LOAD</small><strong><?php echo esc_html($active);?></strong><h3>Projects in motion</h3><p>Click any pipeline stage to filter the command center instantly.</p><div class="tb-command-mini"><span>New <b><?php echo esc_html($counts['new']);?></b></span><span>Review <b><?php echo esc_html($counts['reviewing']);?></b></span><span>Production <b><?php echo esc_html($counts['in-progress']);?></b></span></div></a><?php foreach(array('revision'=>'Client changes','mastering'=>'Final polish','delivery'=>'Ready to send','completed'=>'Finished work') as $key=>$label):?><a class="tb-command-stat" href="<?php echo esc_url(add_query_arg('stage',$key,home_url('/producer-portal/')));?>"><small><?php echo esc_html(strtoupper($key));?></small><strong><?php echo esc_html($counts[$key]);?></strong><span><?php echo esc_html($label);?></span></a><?php endforeach;?></div>
<div class="tb-ops-grid"><section class="tb-ops-card tb-attention"><div class="tb-ops-head"><div><small>PRIORITY</small><h3>Attention Queue</h3></div><b><?php echo esc_html($attention);?></b></div><?php if($attention_items):foreach(array_slice($attention_items,0,6) as $x):?><a href="<?php echo esc_url(tuff_beatz_project_dashboard_url($x['id']).($x['kind']==='MESSAGE'?'#messages':''));?>"><span class="tb-ops-badge<?php echo $x['kind']==='MESSAGE'?' is-message':'';?>"><?php echo esc_html($x['kind']);?></span><div><strong><?php echo esc_html($x['title']);?></strong><small><?php echo esc_html($x['meta']);?></small></div><em>→</em></a><?php endforeach;else:?><p class="tb-ops-empty">Nothing needs immediate attention.</p><?php endif;?></section>
<section class="tb-ops-card"><div class="tb-ops-head"><div><small>SCHEDULE</small><h3>Upcoming Deadlines</h3></div></div><?php if($deadlines):foreach(array_slice($deadlines,0,6) as $d):?><a href="<?php echo esc_url(tuff_beatz_project_dashboard_url($d['id']).'#timeline');?>"><span class="tb-date-chip<?php echo $d['over']?' is-overdue':'';?>"><?php echo esc_html(wp_date('M j',$d['ts']));?></span><div><strong><?php echo esc_html($d['title']);?></strong><small><?php echo esc_html($d['project']);?></small></div></a><?php endforeach;else:?><p class="tb-ops-empty">No milestone deadlines scheduled yet.</p><?php endif;?></section>
<section class="tb-ops-card"><div class="tb-ops-head"><div><small>LIVE FEED</small><h3>Recent Activity</h3></div></div><?php if($activity_feed):foreach(array_slice($activity_feed,0,6) as $a):?><a href="<?php echo esc_url(tuff_beatz_project_dashboard_url($a['id']));?>"><i class="tb-feed-dot"></i><div><strong><?php echo esc_html($a['message']);?></strong><small><?php echo esc_html($a['project'].' • '.human_time_diff(strtotime($a['time']),$now).' ago');?></small></div></a><?php endforeach;else:?><p class="tb-ops-empty">Project activity will appear here.</p><?php endif;?></section></div>
<div class="tb-command-project-tools"><div><p class="tb-card-kicker">ACTIVE WORKSPACE</p><h2>Production Projects</h2></div><form method="get"><input type="search" name="tbq" value="<?php echo esc_attr($search);?>" placeholder="Search artist, project, email…"><select name="stage"><option value="all">All stages</option><?php foreach($counts as $k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($stage,$k);?>><?php echo esc_html(ucwords(str_replace('-',' ',$k)));?> (<?php echo esc_html($v);?>)</option><?php endforeach;?></select><button type="submit">Filter</button><?php if($search||$stage!=='all'):?><a href="<?php echo esc_url(home_url('/producer-portal/'));?>">Clear</a><?php endif;?></form></div>
<?php if($filtered):?><div class="tb-producer-list"><?php foreach($filtered as $p):$id=$p->ID;$status=get_post_meta($id,'_tb_request_status',true)?:'new';$service=get_post_meta($id,'_tb_request_service',true);$artist=get_post_meta($id,'_tb_request_artist',true);$email=get_post_meta($id,'_tb_request_email',true);$progress=tuff_beatz_project_progress_percent($id);$services=tuff_beatz_services();$msg_unread=function_exists('tuff_beatz_conversation_unread')?tuff_beatz_conversation_unread($id,$producer_uid):0;?><article class="tb-producer-row<?php echo $msg_unread?' has-unread-messages':'';?>"><div class="tb-producer-main"><span class="tb-status tb-status--<?php echo esc_attr($status);?>"><?php echo esc_html(tuff_beatz_request_status_label($status));?></span><div><h3><?php echo esc_html($p->post_title);?><?php if($msg_unread):?><a class="tb-row-message-badge" href="<?php echo esc_url(tuff_beatz_project_dashboard_url($id).'#messages');?>" aria-label="<?php echo esc_attr($msg_unread.' unread messages');?>">✉ <?php echo esc_html($msg_unread);?></a><?php endif;?></h3><p><?php echo esc_html($artist?:'Client');?> • <?php echo esc_html($services[$service]??$service);?> • <?php echo esc_html($email);?></p></div></div><div class="tb-producer-progress"><small>PROGRESS</small><strong><?php echo esc_html($progress);?>%</strong><div class="tb-progress"><i style="width:<?php echo esc_attr($progress);?>%"></i></div></div><div class="tb-producer-actions"><a href="<?php echo esc_url(tuff_beatz_project_dashboard_url($id));?>">Open Workspace</a><a href="<?php echo esc_url(admin_url('post.php?post='.$id.'&action=edit'));?>">Manage Project</a></div></article><?php endforeach;?></div><?php else:?><div class="tb-empty-hub"><h3>No matching projects</h3><p>Change the filters or start a new intake.</p></div><?php endif;?></div></section></main><?php get_footer();?>